function toOctal(mode) {
  const bits = mode.slice(1, 4);
  let n = 0;
  if (bits[0] === "r") n += 4;
  if (bits[1] === "w") n += 2;
  if (bits[2] === "x") n += 1;
  return String(n);
}

coding.referenceSolution:
function toOctal(mode) {
  let out = "";
  for (let i = 1; i < 10; i += 3) {
    const bits = mode.slice(i, i + 3);
    let n = 0;
    if (bits[0] === "r") n += 4;
    if (bits[1] === "w") n += 2;
    if (bits[2] === "x") n += 1;
    out += n;
  }
  return out;
}

