function fullMounts(df, threshold) {
  return df
    .split("\n")
    .slice(1)
    .filter(Boolean)
    .map((line) => line.trim().split(/\s+/))
    .filter((cols) => parseInt(cols[4], 10) > threshold)
    .map((cols) => cols[5]);
}

