function listeningPorts(ss) {
  const ports = ss
    .split("\n")
    .slice(1)
    .filter((l) => l.trim())
    .map((l) => l.trim().split(/\s+/))
    .map((cols) => Number(cols[3].slice(cols[3].lastIndexOf(":") + 1)));
  return [...new Set(ports)].sort((a, b) => a - b);
}

