def login_users(passwd):
    users = []
    for line in passwd.splitlines():
        parts = line.split(":")
        if parts[-1] != "/sbin/nologin":
            users.append(parts[0])
    return users

coding.referenceSolution:
def login_users(passwd):
    users = []
    for line in passwd.splitlines():
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        parts = line.split(":")
        shell = parts[6] if len(parts) > 6 else ""
        if not shell or shell.endswith("nologin") or shell == "/bin/false":
            continue
        users.append(parts[0])
    return users

