function loadStatus(uptime, cores) {
  const m = uptime.match(/load average: ([\d.]+)/);
  const perCore = parseFloat(m[1]) / cores;
  if (perCore < 0.7) return "ok";
  if (perCore <= 1.0) return "busy";
  return "overloaded";
}

coding.referenceSolution:
function loadStatus(uptime, cores) {
  const m = uptime.match(/load average: ([\d.]+), ([\d.]+), ([\d.]+)/);
  if (!m) return "unknown";
  const perCore = parseFloat(m[2]) / cores;
  if (perCore < 0.7) return "ok";
  if (perCore <= 1.0) return "busy";
  return "overloaded";
}

