    for line in free_output.splitlines():
        parts = line.split()
        if parts and parts[0] == "Mem:":
            return round(int(parts[3]) / int(parts[1]) * 100)
    return None

coding.referenceSolution:
def mem_available_pct(free_output):
    lines = [l for l in free_output.splitlines() if l.strip()]
    if not lines:
        return None
    header = lines[0].split()
    if "available" not in header:
        return None
    for line in lines[1:]:
        parts = line.split()
        if parts[0] == "Mem:":
            values = [int(v) for v in parts[1:]]
            return round(values[header.index("available")] / values[0] * 100)
    return None
